solution:
def first_unique(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in s:
        if counts[ch] == 1:
            return ch
    return ""

alt:
def first_unique(s):
    for ch in s:
        if s.count(ch) == 1:
            return ch
    return ""
